/**
 * Base premium for all items of one type. A block rate applies only when a
 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
 */
const basePremiumOfType = (type: string, count: number): number => {
  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_PREMIUM;
  }
  return count * basePremiumOf({ type });
};

const quoteResult = (items: Item[]): QuoteResult => {
  let basePremium = 0;
  for (const [type, count] of countByType(items)) {
    basePremium += basePremiumOfType(type, count);
  }
  const premium =
    addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

